mapper.select:
select task_id, user_id, task_title, task_content, start_time, end_time, actual_completion_time, status, priority, sort, kanban_sort, gantt_sort, create_time, update_time, del_flag from task where user_id = #{userId} and del_flag = '0'
and status = #{status}
and end_time >= #{startDate}
and end_time <= #{endDate}
order by sort asc, task_id asc

mapper.update:
update task
set del_flag = '2',
    update_time = sysdate()
where task_id = #{taskId}
  and user_id = #{userId}

update task
set sort = #{sort},
    update_time = sysdate()
where task_id = #{taskId}
  and user_id = #{userId}
  and del_flag = '0'

update task
set kanban_sort = #{kanbanSort},
    update_time = sysdate()
where task_id = #{taskId}
  and user_id = #{userId}
  and del_flag = '0'

update task
set gantt_sort = #{ganttSort},
    update_time = sysdate()
where task_id = #{taskId}
  and user_id = #{userId}
  and del_flag = '0'
